package app.loveu;
import org.json.JSONObject;import android.util.Base64;import java.security.*;import java.nio.charset.StandardCharsets;import javax.crypto.*;import javax.crypto.spec.*;
public final class Backup {
 private static final int ITERATIONS=210000;
 private static byte[] derive(char[] pass,byte[] salt,int rounds)throws Exception{PBEKeySpec spec=new PBEKeySpec(pass,salt,rounds,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
 public static String encode(JSONObject root,String passphrase)throws Exception{if(passphrase==null||passphrase.length()<8)throw new IllegalArgumentException("备份口令至少 8 位");byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(derive(passphrase.toCharArray(),salt,ITERATIONS),"AES"));c.updateAAD("LoveU-backup-1".getBytes(StandardCharsets.UTF_8));JSONObject copy=new JSONObject(root.toString());copy.remove("couple");JSONObject s=copy.getJSONObject("settings");stripDeviceAuthentication(s);copy.put("timer",JSONObject.NULL);return new JSONObject().put("version",1).put("rounds",ITERATIONS).put("salt",b64(salt)).put("iv",b64(c.getIV())).put("data",b64(c.doFinal(copy.toString().getBytes(StandardCharsets.UTF_8)))).toString();}
 public static JSONObject decode(String encoded,String passphrase)throws Exception{if(encoded.length()>30000000)throw new IllegalArgumentException("备份过大");JSONObject j=new JSONObject(encoded);int rounds=j.getInt("rounds");if(j.getInt("version")!=1||rounds<100000||rounds>1000000)throw new IllegalArgumentException("备份格式无效");byte[] salt=Base64.decode(j.getString("salt"),Base64.DEFAULT),iv=Base64.decode(j.getString("iv"),Base64.DEFAULT);if(salt.length!=16||iv.length!=12)throw new IllegalArgumentException("备份格式无效");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(derive(passphrase.toCharArray(),salt,rounds),"AES"),new GCMParameterSpec(128,iv));c.updateAAD("LoveU-backup-1".getBytes(StandardCharsets.UTF_8));JSONObject root=new JSONObject(new String(c.doFinal(Base64.decode(j.getString("data"),Base64.DEFAULT)),StandardCharsets.UTF_8));root.remove("couple");stripDeviceAuthentication(root.getJSONObject("settings"));org.json.JSONArray events=root.getJSONArray("events");for(int i=0;i<events.length();i++)Vault.eventFromJson(events.getJSONObject(i));root.put("timer",JSONObject.NULL);return root;}
 private static void stripDeviceAuthentication(JSONObject settings){
  for(String key:new String[]{"pinSalt","pinHash","pinRounds","pinFailures","pinBlockedUntil","biometricEnabled","biometricCipher","biometricIv","biometricHash"})settings.remove(key);
 }
 private static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}
}
